import { describe, expect, it } from 'vitest';

import schema from './api.schema.json' with { type: 'json' };
import type { MaskingSpec } from './api.gen.js';
import { METHODS, MODE_FOR_STYLE, asRequest, toggleAll, initialState } from '#lib/masking/rules.js';

/**
 * Contract test between frontend masking rules and the types generated by the sidecar.
 * The assignments already trigger type checking; runtime checks verify the enums that
 * TypeScript treats as `string`.
 */
describe('API contract v2', () => {
	const definition = schema.$defs.MaskingSpec;

	it('frontend masking request matches the sidecar MaskingSpec', () => {
		const standard: MaskingSpec = asRequest(initialState());
		const all: MaskingSpec = asRequest(toggleAll(initialState()));
		expect(standard.anonymize).toBe(false);
		expect(all.anonymize).toBe(true);
	});

	it('methods and styles align with the schema', () => {
		expect([...METHODS]).toEqual(definition.properties.method.enum);
		expect(Object.keys(MODE_FOR_STYLE)).toEqual(definition.properties.style.enum);
	});
});
